import React from "react";
import "./HomePage.css";

function HomePage() {
  return (
    <div className="home-page-centerer">
      <div className="home-card pop-in">
        <div className="home-lock">
          <span role="img" aria-label="dashboard">📊</span>
        </div>
        <h2 className="home-title">Welcome to Your CRM Dashboard</h2>
        <p className="home-caption">
          Effortlessly manage customers and grow your business.<br />
          Track interactions and unlock instant analytics—all with one click.
        </p>
        <ul className="home-feature-list">
          <li>👥 <b>Customer Management:</b> Organize, edit, and segment easily.</li>
          <li>📝 <b>Interaction Logging:</b> Record every call, purchase, and feedback.</li>
          <li>📈 <b>Instant Insights:</b> See business stats and trends at a glance.</li>
        </ul>
      </div>
    </div>
  );
}

export default HomePage;
